import pytest

from translate import translate, CODON_TABLE


def test_full_sequence_stops_at_stop_codon():
    assert translate('ATGGCCATTGTAATGGGCCGCTGAAAGGGTGCCCGATAG') == 'MAIVMGR'


def test_no_stop_codon():
    assert translate('ATGAAA') == 'MK'


def test_frame_offset():
    assert translate('AATGGCC', frame=1) == 'MA'


def test_strict_trailing_partial_codon_raises():
    with pytest.raises(ValueError):
        translate('ATGA', strict=True)


def test_non_strict_partial_codon_dropped():
    assert translate('ATGA', strict=False) == 'M'
    assert translate('ATGAA') == 'M'


def test_table_has_64_codons_and_3_stops():
    assert len(CODON_TABLE) == 64
    stops = [aa for aa in CODON_TABLE.values() if aa == '*']
    assert len(stops) == 3

